import{_ as a,o as r,c as l,a2 as i}from"./chunks/framework.DpXDHk3d.js";const c=JSON.parse('{"title":"15.1 理论考试介绍","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/15-chapter-15-li-lun-kao-shi-ying-shi-ji-qiao/15-1-li-lun-kao-shi-jie-shao.md","filePath":"electrician/low-voltage-electrician/15-chapter-15-li-lun-kao-shi-ying-shi-ji-qiao/15-1-li-lun-kao-shi-jie-shao.md","lastUpdated":1795661954000}'),d={name:"electrician/low-voltage-electrician/15-chapter-15-li-lun-kao-shi-ying-shi-ji-qiao/15-1-li-lun-kao-shi-jie-shao.md"};function o(e,t,n,h,s,u){return r(),l("div",null,[...t[0]||(t[0]=[i('<h1 id="_15-1-理论考试介绍" tabindex="-1">15.1 理论考试介绍 <a class="header-anchor" href="#_15-1-理论考试介绍" aria-label="Permalink to &quot;15.1 理论考试介绍&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>理论考试是拿证的&quot;第一关&quot;,形式是<strong>计算机闭卷考试</strong>,当场出分。这一节把考试的性质、题型、分值、范围、报名流程和考场规则讲清楚,让你上机之前心里有数。</p><h2 id="一、考试性质" tabindex="-1">一、考试性质 <a class="header-anchor" href="#一、考试性质" aria-label="Permalink to &quot;一、考试性质&quot;">​</a></h2><p>低压电工特种作业操作证考试分为<strong>理论知识考试</strong>和<strong>实际操作考试</strong>两部分,两部分都合格才能发证。</p><ul><li>理论考试采用**计算机考试(机考)**方式,由各地应急管理部门或其委托的考试机构组织;</li><li>考试成绩当场显示,不合格的按规定参加补考(次数和间隔以当地通知为准);</li><li>理论考试通过后,才有资格参加实操考试(部分地区安排顺序相反,以当地考务为准)。</li></ul><blockquote><p>⚠️ 各地在题量、时长、及格线、补考规则上会有差异,<strong>一律以准考证和当地考务通知为准</strong>。本节的数值是多数地区的通行情况。</p></blockquote><h2 id="二、考试形式与题型" tabindex="-1">二、考试形式与题型 <a class="header-anchor" href="#二、考试形式与题型" aria-label="Permalink to &quot;二、考试形式与题型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>常见情况</th></tr></thead><tbody><tr><td>考试方式</td><td>计算机闭卷机考,当场出分</td></tr><tr><td>主要题型</td><td>判断题 + 单选题</td></tr><tr><td>部分地区题型</td><td>少量多选题</td></tr><tr><td>题量</td><td>一般 100 题左右(判断题 40~50 题,单选题 50~60 题)</td></tr><tr><td>考试时间</td><td>一般 60~90 分钟</td></tr><tr><td>满分</td><td>100 分</td></tr><tr><td>及格线</td><td><strong>80 分</strong></td></tr><tr><td>补考</td><td>不合格可按规定补考,以当地通知为准</td></tr></tbody></table><h3 id="_1-判断题" tabindex="-1">1. 判断题 <a class="header-anchor" href="#_1-判断题" aria-label="Permalink to &quot;1. 判断题&quot;">​</a></h3><ul><li>二选一,只判断&quot;对&quot;或&quot;错&quot;;</li><li>单题分值低,但数量多,是<strong>拿分的基本盘</strong>;</li><li>常考三类:<strong>绝对化表述、数值、操作顺序</strong>。</li></ul><h3 id="_2-单选题" tabindex="-1">2. 单选题 <a class="header-anchor" href="#_2-单选题" aria-label="Permalink to &quot;2. 单选题&quot;">​</a></h3><ul><li>四个选项中选出<strong>最符合题意</strong>的一个;</li><li>常见形式:数值题、概念辨析题、场景应用题(&quot;应该怎么做&quot;);</li><li>题干里常出现&quot;首先&quot;&quot;最主要&quot;&quot;应选用&quot;&quot;不属于&quot;等关键词,读题时先圈出来。</li></ul><h3 id="_3-多选题-部分地区" tabindex="-1">3. 多选题(部分地区) <a class="header-anchor" href="#_3-多选题-部分地区" aria-label="Permalink to &quot;3. 多选题(部分地区)&quot;">​</a></h3><ul><li>少选、多选、错选通常都不得分(以当地规则为准);</li><li>策略是&quot;先确定一定对的,再排除一定错的&quot;,宁少勿滥。</li></ul><h2 id="三、考试内容范围" tabindex="-1">三、考试内容范围 <a class="header-anchor" href="#三、考试内容范围" aria-label="Permalink to &quot;三、考试内容范围&quot;">​</a></h2><p>理论考试覆盖低压电工上岗必须掌握的全部知识,大致可以分为七大模块:</p><table tabindex="0"><thead><tr><th>模块</th><th>主要内容</th><th>大致占比</th></tr></thead><tbody><tr><td>安全生产法律法规</td><td>安全生产法、特种作业管理制度、电工职责与法律责任</td><td>约 15%</td></tr><tr><td>电工基础知识</td><td>电路组成、欧姆定律、串并联、交流电、电磁感应</td><td>约 20%</td></tr><tr><td>电气安全技术</td><td>触电方式、安全电压与安全电流、接地接零、漏电保护</td><td>约 20%</td></tr><tr><td>仪表与低压电器</td><td>万用表、钳形表、兆欧表、断路器、接触器、继电器</td><td>约 15%</td></tr><tr><td>线路、变压器与电动机</td><td>导线选择、变压器、三相异步电动机</td><td>约 15%</td></tr><tr><td>配电、照明与防雷接地</td><td>低压配电系统、照明、防雷与接地</td><td>约 10%</td></tr><tr><td>防火防爆与触电急救</td><td>电气火灾、灭火器选择、心肺复苏、现场急救</td><td>约 5%</td></tr></tbody></table><blockquote><p>💡 占比只是估算,不同地区、不同批次的题库权重会有浮动。安全技术、基础知识和法规三块加起来接近一半,是复习重点。</p></blockquote><h2 id="四、报名与考试流程" tabindex="-1">四、报名与考试流程 <a class="header-anchor" href="#四、报名与考试流程" aria-label="Permalink to &quot;四、报名与考试流程&quot;">​</a></h2><ol><li><strong>报名</strong>:通过有资质的培训机构或当地应急管理部门指定的渠道报名;</li><li><strong>资格审核</strong>:提交身份证明、学历证明、健康承诺(或体检)等材料;</li><li><strong>安全技术培训</strong>:按培训大纲完成规定学时,包括理论与实操;</li><li><strong>参加理论考试</strong>:机考,当场出分;</li><li><strong>参加实操考试</strong>:理论合格后按安排参加;</li><li><strong>制证与领证</strong>:两部分均合格后,由发证机关制证发放。</li></ol><h2 id="五、考场规则与注意事项" tabindex="-1">五、考场规则与注意事项 <a class="header-anchor" href="#五、考场规则与注意事项" aria-label="Permalink to &quot;五、考场规则与注意事项&quot;">​</a></h2><ul><li>带齐<strong>准考证和身份证</strong>,按通知提前到达考场;</li><li>不得携带书籍、资料、手机等电子设备进入考位;</li><li>按座位号入座,先核对屏幕上显示的姓名、证件号是否正确;</li><li>机考操作:选中答案后确认,注意<strong>不要漏答</strong>;交卷前系统一般会提示未作答题数;</li><li>即使时间充裕也不要急着交卷,至少完整复查一遍;</li><li>考场内保持安静,遇到设备故障立即举手报告监考人员,不要自行处理。</li></ul><h2 id="六、成绩、证书与复审" tabindex="-1">六、成绩、证书与复审 <a class="header-anchor" href="#六、成绩、证书与复审" aria-label="Permalink to &quot;六、成绩、证书与复审&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>发证条件</td><td>理论、实操均合格</td></tr><tr><td>证书有效期</td><td><strong>6 年</strong></td></tr><tr><td>复审</td><td>每 <strong>3 年</strong>复审一次</td></tr><tr><td>复审要求</td><td>复审前应参加必要的安全培训并考试合格</td></tr><tr><td>证书效力</td><td>全国通用,跨地区作业按规定办理相关手续</td></tr><tr><td>证件遗失</td><td>向发证机关申请补发,不得使用复印件或借用他人证件</td></tr></tbody></table><h2 id="七、高频提问" tabindex="-1">七、高频提问 <a class="header-anchor" href="#七、高频提问" aria-label="Permalink to &quot;七、高频提问&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>回答</th></tr></thead><tbody><tr><td>理论考试多少分及格?</td><td>一般满分 100 分,80 分及格(以当地通知为准)</td></tr><tr><td>判断题和单选题先做哪个?</td><td>先做有把握的判断题,把能拿的分先拿到</td></tr><tr><td>考试能带手机吗?</td><td>不能,电子设备一律不得带入考位</td></tr><tr><td>理论没过能直接考实操吗?</td><td>一般不能,需理论合格后按安排参加实操</td></tr><tr><td>证书多久复审一次?</td><td>每 3 年一次,有效期 6 年</td></tr><tr><td>复审要考试吗?</td><td>复审前应参加必要的安全培训并考试合格</td></tr></tbody></table><h2 id="八、考点提示" tabindex="-1">八、考点提示 <a class="header-anchor" href="#八、考点提示" aria-label="Permalink to &quot;八、考点提示&quot;">​</a></h2><ul><li>✅ 理论考试为机考,满分 100 分,<strong>80 分及格</strong>;</li><li>✅ 题型以<strong>判断题 + 单选题</strong>为主,部分地区有多选题;</li><li>✅ 证书有效期 <strong>6 年</strong>,每 <strong>3 年</strong>复审一次,复审前需参加安全培训并考试合格;</li><li>✅ 考试范围以法规、基础、安全技术为主,三块合计接近一半;</li><li>⚠️ 题量、时长、及格线、补考规则各地不同,<strong>以考务通知为准</strong>。</li></ul><h2 id="九、本节小结" tabindex="-1">九、本节小结 <a class="header-anchor" href="#九、本节小结" aria-label="Permalink to &quot;九、本节小结&quot;">​</a></h2><ul><li>理论考试是机考,当场出分,判断题 + 单选题为主,80 分及格。</li><li>考试内容分七大模块,法规、基础、安全技术是重点。</li><li>报名走&quot;报名 → 审核 → 培训 → 理论 → 实操 → 发证&quot;流程。</li><li>证书 6 年有效,3 年复审,复审前要培训并考试合格。</li><li>具体考务细节以当地通知为准,不要照搬别人的经验。</li></ul><h2 id="十、自测练习" tabindex="-1">十、自测练习 <a class="header-anchor" href="#十、自测练习" aria-label="Permalink to &quot;十、自测练习&quot;">​</a></h2><ol><li>(判断)低压电工理论考试一般采用计算机考试方式,当场出分。( )</li><li>(单选)低压电工理论考试的及格线一般为( )分。 A. 60　B. 70　C. 80　D. 90</li><li>(单选)特种作业操作证的有效期和复审周期分别是( )。 A. 3 年、1 年　B. 6 年、3 年　C. 6 年、6 年　D. 10 年、5 年</li><li>(判断)理论考试不合格,可以直接参加实操考试。( )</li><li>(单选)下列不属于理论考试主要题型的是( )。 A. 判断题　B. 单选题　C. 多选题(部分地区)　D. 现场接线操作</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。理论考试为机考,当场出分。</li><li><strong>C</strong>。多数地区满分 100 分、80 分及格,以当地通知为准。</li><li><strong>B</strong>。证书 6 年有效,每 3 年复审一次。</li><li><strong>×</strong>。一般要求理论合格后才能参加实操考试。</li><li><strong>D</strong>。现场接线操作属于实操考试,不是理论机考的题型。</li></ol></details>',34)])])}const q=a(d,[["render",o]]);export{c as __pageData,q as default};
